import React, { useState } from 'react';
import axios from 'axios';

export default function TeacherActivities({ timetable, teachingSubject, userName }) {
  const teacherGrades = Array.isArray(timetable) ? [...new Set(timetable.map(c => c.grade))] : [];
  
  // 🟢 SMART LOGIC: කෝඩ් එකේ ප්‍රශ්න නැත! ඔයා දාන ඒවා රිෆ්‍රෙෂ් කළත් මැකෙන්නේ නැතිවෙන්න LocalStorage එකට සම්බන්ධ කළා
  const [publishedMathItems, setPublishedMathItems] = useState(() => {
    const savedItems = localStorage.getItem('aura_math_worksheet');
    return savedItems ? JSON.parse(savedItems) : [];
  });

  // Form States
  const [tfGrade, setTfGrade] = useState(teacherGrades[0] || 'Grade 8');
  const [tfQuestion, setTfQuestion] = useState('');
  const [tfAnswer, setTfAnswer] = useState('True');

  const [fibGrade, setFibGrade] = useState(teacherGrades[0] || 'Grade 8');
  const [fibQuestion, setFibQuestion] = useState('');
  const [fibAnswer, setFibAnswer] = useState('');

  const [noticeGrade, setNoticeGrade] = useState(teacherGrades[0] || 'Grade 8');
  const [noticeType, setNoticeType] = useState('Weekly Math Challenge');
  const [noticeContent, setNoticeContent] = useState('');

  // LocalStorage එකට ඩේටා සේව් කරන පොදු function එක
  const saveToStorage = (newItems) => {
    setPublishedMathItems(newItems);
    localStorage.setItem('aura_math_worksheet', JSON.stringify(newItems));
  };

  const handleTfSubmit = (e) => {
    e.preventDefault();
    const newItem = { id: Date.now(), type: 'true_false', grade: tfGrade, question: tfQuestion, answer: tfAnswer === 'True' ? 'ප්‍රකාශය සත්‍ය වේ (TRUE)' : 'ප්‍රකාශය අසත්‍ය වේ (FALSE)' };
    const updated = [newItem, ...publishedMathItems];
    saveToStorage(updated);
    alert("✅ ගණිත ප්‍රකාශය සාර්ථකව Worksheet එකට එකතු වුණා!");
    setTfQuestion('');
  };

  const handleFibSubmit = (e) => {
    e.preventDefault();
    const newItem = { id: Date.now(), type: 'fill_blanks', grade: fibGrade, question: fibQuestion, answer: fibAnswer };
    const updated = [newItem, ...publishedMathItems];
    saveToStorage(updated);
    alert("✅ හිස්තැන් පුරවන ගණිත ගැටලුව එකතු වුණා!");
    setFibQuestion(''); setFibAnswer('');
  };

  const handleNoticeSubmit = (e) => {
    e.preventDefault();
    const newItem = { id: Date.now(), type: 'announcement', grade: noticeGrade, question: `${noticeType}: ${noticeContent}`, answer: 'Notice Board Post' };
    const updated = [newItem, ...publishedMathItems];
    saveToStorage(updated);
    alert(`📢 ${noticeType} නිවේදනය ගණිත පුවරුවට එකතු කරන ලදි!`);
    setNoticeContent('');
  };

  // 🟢 Worksheet එක සම්පූර්ණයෙන්ම හිස් කිරීමට (Reset) අවශ්‍ය නම් පාවිච්චි කරන බටන් ලොජික් එක
  const handleClearWorksheet = () => {
    if (window.confirm("ඔබ ඇතුළත් කළ සියලුම ප්‍රශ්න පත්‍ර දත්ත මකා දැමීමට වග බලා ගන්නද?")) {
      saveToStorage([]);
    }
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '30px', fontFamily: 'sans-serif' }}>
      
      <div>
        <h2 style={{ color: '#1e293b', margin: 0 }}>
          📐 Mathematics Interactive Worksheet Builder
        </h2>
        <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px' }}>
          ගණිතමය සමීකරණ, ජ්‍යාමිතික ප්‍රමේයයන් සහ සතිපතා විශේෂ විශේෂ ගණිත ගැටලු විවරණයන් සිසුන් වෙනුවෙන් මෙතැනින් සකසන්න.
        </p>
      </div>

      {/* THREE MATH FORMS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(310px, 1fr))', gap: '25px' }}>
        
        {/* Panel 1 */}
        <div style={styles.card('#15803d')}>
          <h3 style={styles.cardTitle}>📐 ජ්‍යාමිතිය හා ප්‍රමේයයන් (True / False)</h3>
          <p style={styles.cardDesc}>ගණිත ප්‍රකාශයන්හි නිවැරදිතාවය පරීක්ෂා කිරීමට කෙටි ප්‍රශ්න දමන්න.</p>
          <form onSubmit={handleTfSubmit} style={styles.formGap}>
            <select value={tfGrade} onChange={e => setTfGrade(e.target.value)} style={styles.inputStyle}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <input type="text" placeholder="ප්‍රකාශය (e.g., ත්‍රිකෝණයක අභ්‍යන්තර කෝණවල එකතුව 180° කි.)" value={tfQuestion} onChange={e => setTfQuestion(e.target.value)} required style={styles.inputStyle} />
            <select value={tfAnswer} onChange={e => setTfAnswer(e.target.value)} style={styles.inputStyle}>
              <option value="True">ප්‍රකාශය සත්‍ය වේ (TRUE)</option>
              <option value="False">ප්‍රකාශය අසත්‍ය වේ (FALSE)</option>
            </select>
            <button type="submit" style={styles.btnStyle('#15803d')}>Add to Worksheet</button>
          </form>
        </div>

        {/* Panel 2 */}
        <div style={styles.card('#7c3aed')}>
          <h3 style={styles.cardTitle}>🔢 සමීකරණ හා සුළුකිරීම් (Fill in Blanks)</h3>
          <p style={styles.cardDesc}>සමීකරණ විසඳා අවසන් පිළිතුර හිස්තැනට ලිවීමට ප්‍රශ්න සකසන්න.</p>
          <form onSubmit={handleFibSubmit} style={styles.formGap}>
            <select value={fibGrade} onChange={e => setFibGrade(e.target.value)} style={styles.inputStyle}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <input type="text" placeholder="ගැටලුව (e.g., 2x + 5 = 15 නම්, x හි අගය _______ වේ.)" value={fibQuestion} onChange={e => setFibQuestion(e.target.value)} required style={styles.inputStyle} />
            <input type="text" placeholder="නිවැරදි අගය (e.g., 5)" value={fibAnswer} onChange={e => setFibAnswer(e.target.value)} required style={styles.inputStyle} />
            <button type="submit" style={styles.btnStyle('#7c3aed')}>Add Math Blank</button>
          </form>
        </div>

        {/* Panel 3 */}
        <div style={styles.card('#ea580c')}>
          <h3 style={styles.cardTitle}>📢 ගණිත පුවරුව හා ගැටලු විවරණ (Notice)</h3>
          <p style={styles.cardDesc}>සතිපතා විශේෂ ගණිත අභියෝග හෝ ළමයින්ට ඇති ගැටලු විසඳන පුවරුව.</p>
          <form onSubmit={handleNoticeSubmit} style={styles.formGap}>
            <select value={noticeGrade} onChange={e => setNoticeGrade(e.target.value)} style={styles.inputStyle}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <select value={noticeType} onChange={e => setNoticeType(e.target.value)} style={styles.inputStyle}>
              <option value="Weekly Math Challenge">🎯 සතිපතා විශේෂ ගණිත අභියෝගය</option>
              <option value="Syllabus Coverage Notice">📅 වාර විභාග විශේෂ නිවේදන</option>
              <option value="Step-by-Step Explanation">💬 සංකීර්ණ ගණන් විසඳන කෙටි ක්‍රම</option>
            </select>
            <textarea placeholder="ගණිතමය පියවර හෝ විශේෂ දැනුම්දීම මෙතන පැහැදිලිව ලියන්න..." value={noticeContent} onChange={e => setNoticeContent(e.target.value)} required style={styles.textareaStyle} />
            <button type="submit" style={styles.btnStyle('#ea580c')}>Post to Math Board</button>
          </form>
        </div>

      </div>

      {/* LIVE PREVIEW WORKSHEET SHEET */}
      <div style={{ marginTop: '10px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <h3 style={{ color: '#1e293b', margin: 0 }}>📝 Live Math Activity Worksheet Preview</h3>
          {publishedMathItems.length > 0 && (
            <button onClick={handleClearWorksheet} style={{ backgroundColor: '#fee2e2', color: '#b91c1c', border: '1px solid #fca5a5', padding: '6px 12px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' }}>
              🗑️ Reset Paper (Worksheet එක හිස් කරන්න)
            </button>
          )}
        </div>
        
        <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 10px 30px rgba(0,0,0,0.02)' }}>
          
          <div style={{ borderBottom: '2px dashed #cbd5e1', paddingBottom: '20px', marginBottom: '25px', textAlign: 'center' }}>
            <span style={{ fontSize: '11px', fontWeight: 'bold', color: '#15803d', letterSpacing: '2px', backgroundColor: '#e0f2fe', padding: '4px 12px', borderRadius: '12px' }}>
              AURA INSTITUTIONAL MATHEMATICS UNIT
            </span>
            <h4 style={{ margin: '10px 0 0 0', fontSize: '18px', color: '#334155' }}>Daily Evaluation & Knowledge Recall Sheet</h4>
            <p style={{ margin: '3px 0 0 0', fontSize: '13px', color: '#94a3b8' }}>Subject structure verified by Lecturer: {userName}</p>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            {publishedMathItems.length > 0 ? (
              publishedMathItems.map((item, idx) => (
                <div key={item.id || idx} style={{ display: 'flex', gap: '15px', padding: '15px', borderRadius: '10px', backgroundColor: '#f8fafc', borderLeft: item.type === 'true_false' ? '4px solid #15803d' : item.type === 'fill_blanks' ? '4px solid #7c3aed' : '4px solid #ea580c' }}>
                  
                  <div style={{ width: '26px', height: '26px', borderRadius: '50%', backgroundColor: '#cbd5e1', color: '#334155', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px', fontWeight: 'bold', flexShrink: 0 }}>
                    {idx + 1}
                  </div>

                  <div style={{ flex: 1 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '4px' }}>
                      <span style={{ fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase', color: item.type === 'true_false' ? '#15803d' : item.type === 'fill_blanks' ? '#7c3aed' : '#ea580c' }}>
                        {item.type === 'true_false' ? '💡 Geometry Theorem' : item.type === 'fill_blanks' ? '🔢 Equation Slot' : '📢 Notice Board'}
                      </span>
                      <span style={{ fontSize: '11px', backgroundColor: '#e2e8f0', padding: '2px 6px', borderRadius: '4px', fontWeight: '600' }}>
                        {item.grade}
                      </span>
                    </div>
                    <p style={{ margin: 0, color: '#1e293b', fontSize: '14.5px', fontWeight: '500', lineHeight: '1.5' }}>{item.question}</p>
                    
                    <div style={{ marginTop: '8px', fontSize: '12px', color: '#64748b' }}>
                      🔑 Correct System Schema Answer: <strong style={{ color: '#334155' }}>{item.answer}</strong>
                    </div>
                  </div>

                </div>
              ))
            ) : (
              <div style={{ textAlign: 'center', padding: '30px', color: '#94a3b8', fontStyle: 'italic' }}>
                📭 දැනට ප්‍රශ්න පත්‍රය හිස්ව පවතී. ඉහත පැනල භාවිතයෙන් ඔබේම ගණිත ප්‍රශ්න එකතු කරන්න.
              </div>
            )}
          </div>

          <div style={{ marginTop: '30px', textAlign: 'right', fontSize: '11px', color: '#94a3b8', fontStyle: 'italic' }}>
            System Matrix Core: Generated via Aura Pen Saku Live Engine Matrix.
          </div>

        </div>
      </div>

    </div>
  );
}

const styles = {
  card: (color) => ({ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column' }),
  cardTitle: { margin: '0 0 5px 0', fontSize: '16px', color: '#1e293b', fontWeight: 'bold' },
  cardDesc: { margin: '0 0 15px 0', fontSize: '12.5px', color: '#64748b', lineHeight: '1.4' },
  formGap: { display: 'flex', flexDirection: 'column', gap: '12px' },
  inputStyle: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', fontSize: '13.5px', boxSizing: 'border-box' },
  textareaStyle: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', fontSize: '13.5px', boxSizing: 'border-box', height: '75px', resize: 'none' },
  btnStyle: (color) => ({ width: '100%', padding: '11px', backgroundColor: color, color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13.5px', marginTop: '5px' })
};
